// Pull the post scheduled for today out of calendar.json.
// calendar.json is mounted/available to n8n. Two supported sources:
//   A) Read from disk via the Read Binary File node (swap this node out), or
//   B) Paste the calendar contents into a workflow static-data / env var.
// This Code node expects the calendar JSON to arrive on $json.calendar, or
// falls back to the CALENDAR_JSON env var so the workflow is portable.

const raw = $json.calendar || $env.CALENDAR_JSON;
if (!raw) {
  throw new Error('No calendar found. Wire a Read File node into this node, or set CALENDAR_JSON env.');
}
const cal = typeof raw === 'string' ? JSON.parse(raw) : raw;

// Today's date in the calendar timezone (America/New_York), YYYY-MM-DD.
const tz = (cal.meta && cal.meta.timezone) || 'America/New_York';
const today = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());

const post = (cal.posts || []).find((p) => p.date === today);
if (!post) {
  // No post today. Stop quietly.
  return [];
}

const site = (cal.meta && cal.meta.site) || 'https://localtrafficai.com';
const id = String(post.id).padStart(2, '0');
const assetFile = `${post.date}_post-${id}_${post.pillar}.png`;

// Full IG caption: body + a blank line + hashtags.
const caption = `${post.caption}\n\n${(post.hashtags || []).join(' ')}`;

// Public URL where the rendered asset is hosted. The IG Graph API needs a
// publicly reachable image_url. Set ASSET_BASE_URL to wherever you host the
// files in content/assets/ (S3, Cloudflare R2, a static host, etc.).
const assetBase = ($env.ASSET_BASE_URL || 'https://CHANGE-ME.example.com/assets').replace(/\/$/, '');
const image_url = `${assetBase}/${encodeURIComponent(assetFile)}`;

return [{ json: { post_id: post.id, date: post.date, pillar: post.pillar, caption, image_url, asset_file: assetFile, site } }];

const media = $json;
const meta = $('Pick Today\'s Post').item.json;
return [{ json: { status: 'posted', published_media_id: media.id, post_id: meta.post_id, date: meta.date, pillar: meta.pillar, posted_at: new Date().toISOString() } }];
